issue.body:
To reproduce:

Copy a couple gltfs from the bevy repo.

```
cp ../bevy/assets/models/AlienCake/alien.glb bevy_asset_loader/assets
cp ../bevy/assets/models/mask.glb bevy_asset_loader/assets  
```

Modify `two_collections.rs` to use them.

```diff
diff --git a/bevy_asset_loader/examples/two_collections.rs b/bevy_asset_loader/examples/two_collections.rs
index 988ecff..38e7d4e 100644
--- a/bevy_asset_loader/examples/two_collections.rs
+++ b/bevy_asset_loader/examples/two_collections.rs
@@ -11,7 +11,7 @@ fn main() {
         .add_loading_state(
             LoadingState::new(MyStates::AssetLoading).continue_to_state(MyStates::Next),
         )
-        .add_collection_to_loading_state::<_, ImageAssets>(MyStates::AssetLoading)
+        .add_collection_to_loading_state::<_, GltfAssets>(MyStates::AssetLoading)
         .add_collection_to_loading_state::<_, AudioAssets>(MyStates::AssetLoading)
         .insert_resource(Msaa::Off)
         .add_systems(
@@ -29,31 +29,22 @@ struct AudioAssets {
 }
 
 #[derive(AssetCollection, Resource)]
-struct ImageAssets {
-    #[asset(path = "images/player.png")]
-    player: Handle<Image>,
-    #[asset(path = "images/tree.png")]
-    tree: Handle<Image>,
-    #[asset(path = "images", collection)]
-    _images: Vec<UntypedHandle>,
+pub struct GltfAssets {
+    #[asset(path = "alien.glb#Scene0")]
+    pub alien: Handle<Scene>,
+    #[asset(path = "mask.glb#Scene0")]
+    pub mask: Handle<Scene>,
 }
 
 #[derive(Component)]
 struct Player;
 
-fn spawn_player_and_tree(mut commands: Commands, image_assets: Res<ImageAssets>) {
-    commands.spawn(Camera2dBundle::default());
-    commands
-        .spawn(SpriteBundle {
-            texture: image_assets.player.clone(),
-            transform: Transform::from_translation(Vec3::new(0., 0., 1.)),
-            ..Default::default()
-        })
-        .insert(Player);
-    commands.spawn(SpriteBundle {
-        texture: image_assets.tree.clone(),
-        transform: Transform::from_translation(Vec3::new(50., 30., 1.)),
-        ..Default::default()
+fn spawn_player_and_tree(mut commands: Commands, gltf_assets: Res<GltfAssets>) {
+    commands.spawn(Camera3dBundle::default());
+    commands.spawn(SceneBundle {
+        scene: gltf_assets.alien.clone(),
+        transform: Transform::from_translation(Vec3::ZERO).with_scale(Vec3::splat(0.25)),
+        ..default()
     });
 }
```

Run that example.

`cargo run --example two_collections`
